// ── #191 + #196 + #193: via svc_handle_request (the daemon router) ─────────────

fn w4_ctx(rpm f64) ServeContext {
	caps_set_all()
	mut lim := new_limiter(LimitConfig{
		per_principal_rate: rpm / 60.0
		per_principal_conc: 64
		pre_auth_rate:      rpm / 60.0
		pre_auth_burst:     1.0 // tiny burst so the 2nd pre-auth request trips
	})
	return ServeContext{
		mounts:  {
			'docs': w4_open('svc')
		}
		limiter: lim
	}
}

fn test_rate_limit_has_retry_after() {
	mut s := new_service_state()
	s.mark_ready()
	ctx := w4_ctx(60.0)
	// first request consumes the tiny pre-auth burst; the second trips 429.
	_ := svc_handle_request(w4_req('GET', '/cx-store/v1/capabilities', ''), mut s, ctx)
	mut got429 := false
	for _ in 0 .. 5 {
		r := svc_handle_request(w4_req('POST', '/cx-store/v1/docs/list', ''), mut s, ctx)
		if w4_status(r) == 429 {
			got429 = true
			assert w4_header(r, 'Retry-After') != '', '429 must carry a Retry-After header (#191); headers missing'
			break
		}
	}
	assert got429, 'expected a 429 under the tiny pre-auth burst'
}

fn test_per_store_capabilities_and_unknown_404() {
	mut s := new_service_state()
	s.mark_ready()
	caps_set_all()
	ctx := ServeContext{
		mounts: {
			'docs': w4_open('caps')
		}
	}
	// server-level: no backend fields, cxbin advertised
	srv := svc_handle_request(w4_req('GET', '/cx-store/v1/capabilities', ''), mut s, ctx)
	assert w4_status(srv) == 200
	assert w4_body(srv).contains('"cxbin"'), 'server-level caps must advertise cxbin (#193); got ${w4_body(srv)}'
	// per-store: backend-name + query-features + real flags
	per := svc_handle_request(w4_req('GET', '/cx-store/v1/docs/capabilities', ''), mut s, ctx)
	assert w4_status(per) == 200
	assert w4_body(per).contains('backend-name'), 'per-store caps must carry backend-name (#193)'
	assert w4_body(per).contains('query-features'), 'per-store caps must carry query-features (#193)'
	// unknown store → 404 CXER1710 (not an oracle-free 200)
	unk := svc_handle_request(w4_req('GET', '/cx-store/v1/nope/capabilities', ''), mut s, ctx)
	assert w4_status(unk) == 404, 'unknown-store capabilities must 404 (#193), not 200; got ${w4_status(unk)}'
	assert w4_body(unk).contains('CXER1710'), 'unknown-store 404 carries CXER1710'
}

fn test_request_size_cap_413() {
	mut s := new_service_state()
	s.mark_ready()
	caps_set_all()
	ctx := ServeContext{
		mounts: {
			'docs': w4_open('big')
		}
	}
	// a body over the 16 MiB cap → 413 CXER1705 (#196; was unreachable).
	big := '['.repeat(1) + 'x'.repeat(int(svc_max_request_bytes) + 16) + ']'
	r := svc_handle_request(w4_req('POST', '/cx-store/v1/docs/put', big), mut s, ctx)
	assert w4_status(r) == 413, 'oversized body must be 413 (#196); got ${w4_status(r)}'
	assert w4_body(r).contains('CXER1705'), '413 carries CXER1705'
}

// ── #194: gRPC status maps carry the exact cx-err:CXERnnnn ─────────────────────

fn test_grpc_trailer_cxer() {
	// 413 and 429 share RESOURCE_EXHAUSTED(8) but the cx_err disambiguates.
	s413 := grpc_status_for_cxer('cx-err:CXER1705')
	s429 := grpc_status_for_cxer('cx-err:CXER1706')
	assert s413.code == grpc_resource_exhausted && s429.code == grpc_resource_exhausted, 'both are RESOURCE_EXHAUSTED'
	assert s413.cx_err == 'cx-err:CXER1705', 'trailer must carry exact CXER1705, got ${s413.cx_err}'
	assert s429.cx_err == 'cx-err:CXER1706', 'trailer must carry exact CXER1706, got ${s429.cx_err}'
	// 1709/1710 mapped (W0 parity rows)
	assert grpc_status_for_cxer('cx-err:CXER1709').code == grpc_unimplemented
	assert grpc_status_for_cxer('cx-err:CXER1710').code == grpc_not_found
}

// ── #198: config-invalid uses CXER1711, NOT CXER1140 (handle-race) ────────────

fn test_config_error_code_distinct() {
	if _ := parse_service_config('[not-a-service-config]') {
		assert false, 'bad config must be rejected'
	} else {
		assert err.msg().contains('CXER1711'), 'config error must be CXER1711 E_SVC_CONFIG_INVALID (#198), not CXER1140; got ${err.msg()}'
		assert !err.msg().contains('CXER1140'), 'config error must NOT reuse CXER1140 (handle-race)'
	}
}

// ── URL userinfo redaction (#644) — the log/banner guard. The service wire
// refuses URL userinfo outright (R1.3), so the carriers this fn still guards
// are ftp/sftp `user:pass@` mounts and any legacy-shaped URL that reaches a
// log line. Pure fn, pinned directly.
fn test_url_userinfo_redaction() {
	assert store_url_redact_userinfo('ftp://user:pass@host:21/dir/') == 'ftp://***@host:21/dir/'
	assert store_url_redact_userinfo('sftp://deploy@host/dir/') == 'sftp://***@host/dir/'
	// no userinfo → unchanged
	assert store_url_redact_userinfo('cx-store+xsp://127.0.0.1:9000/main/') == 'cx-store+xsp://127.0.0.1:9000/main/'
	// an @ in the PATH is data, not userinfo
	assert store_url_redact_userinfo('https://host/path@v1') == 'https://host/path@v1'
}

// ── source: vcx/platform/store_xsp_alias_retract_test.v ──
// R3.4 (audit F-26): the alias-retract feed SHAPE. `aliases-delete` is not
// carried on the XSP/CSRP wire (delete-alias is a daemon-side operation, see
// stdlib_store.v), so the `[retract plane="aliases" …]` feed act cannot be
// produced by a wire verb the daemon-driven serve test can send. Pinned here
// in-process, end to end: a local alias delete appends a retract act, and the
// §5.3 feed formatter (sx_render_advance) renders it in the spec shape —
// distinct from the alias-ADVANCE shape (which the daemon serve test covers).

fn ar_store() MemStore {
	return MemStore{
		url:         'mem://alias-retract'
		backend:     'mem'
		is_open:     true
		docs:        map[string]string{}
		doc_order:   []string{}
		aliases:     map[string]string{}
		alias_order: []string{}
		adv_pos:     map[string]i64{}
	}
}

fn test_alias_retract_feed_shape() {
	mut ms := ar_store()
	// set then delete — the delete funnel appends the retract act
	store_alias_set_local(mut ms, 'pinned', 'sha2-256:${'ab'.repeat(32)}')
	assert store_alias_delete_local(mut ms, 'pinned'), 'delete of a live alias must succeed'

	// the last act on the aliases stream is a retract for that name
	mut retract := StoreAdvance{}
	mut found := false
	for a in ms.advances {
		if a.plane == 'aliases' && a.kind == 'retract' && a.name == 'pinned' {
			retract = a
			found = true
		}
	}
	assert found, 'delete-alias must append an aliases-retract act (${ms.advances.len} acts)'

	// the §5.3 formatter renders the retract shape — NOT an advance
	local := cx.Node(cx.Element{})
	frame := sx_render_advance(mut ms, local, retract, false)
	assert frame == '[retract plane="aliases" name="pinned" pos=${retract.pos}]', 'alias-retract shape: ${frame}'
	assert !frame.contains('advance'), 'a retract must never render as an advance: ${frame}'

	// deleting an absent alias is a no-op — no spurious retract act
	before := ms.advances.len
	assert !store_alias_delete_local(mut ms, 'never-existed'), 'deleting an absent alias returns false'
	assert ms.advances.len == before, 'a no-op delete must append no act'
}

// ── source: vcx/platform/store_observability_test.v ──
// store_observability_test.v — BEHAVIORAL tests for the metrics registry +
// Prometheus exposition (observability sub-area, spec Appendix F). Deterministic:
// durations/bytes are injected, never wall-clock. The scope-gated /metrics
// endpoint tests live in store_service_test.v (where the request/ctx fixtures are
// — V compiles each _test.v as its own binary, so helpers are not shared).
// ── registry unit: exposition shape ─────────────────────────────────────────

fn test_registry_exposition_basic() {
	mut m := new_metrics_registry('0.12.0-test')
	m.record_request('get', 200, 'docs', 10, 100, 0.003)
	m.record_request('get', 200, 'docs', 20, 200, 0.007)
	m.record_request('put', 200, 'docs', 50, 5, 0.02)
	m.record_request('get', 404, 'docs', 0, 12, 0.001)
	out := m.render_prometheus()

	// build_info always present with the version label
	assert out.contains('cxstore_build_info{version="0.12.0-test"} 1'), out
	// request counters by (endpoint,status,store)
	assert out.contains('cxstore_requests_total{endpoint="get",status="200",store="docs"} 2'), out
	assert out.contains('cxstore_requests_total{endpoint="put",status="200",store="docs"} 1'), out
	assert out.contains('cxstore_requests_total{endpoint="get",status="404",store="docs"} 1'), out
	// bytes counters (summed per endpoint,store across statuses)
	assert out.contains('cxstore_request_bytes_in_total{endpoint="get",store="docs"} 30'), out
	assert out.contains('cxstore_request_bytes_out_total{endpoint="get",store="docs"} 312'), out
	// histogram has the canonical TYPE line + a +Inf bucket + sum/count
	assert out.contains('# TYPE cxstore_request_duration_seconds histogram'), out
	assert out.contains('cxstore_request_duration_seconds_bucket{endpoint="get",store="docs",le="+Inf"} 3'), out
	assert out.contains('cxstore_request_duration_seconds_count{endpoint="get",store="docs"} 3'), out
	// inflight gauge present (0 at rest)
	assert out.contains('cxstore_inflight_requests 0'), out
}

fn test_histogram_buckets_cumulative() {
	mut m := new_metrics_registry('v')
	// three obs: 3ms, 7ms, 20ms → le=0.005 covers 1, le=0.01 covers 2, le=0.025 covers 3
	m.record_request('get', 200, 's', 0, 0, 0.003)
	m.record_request('get', 200, 's', 0, 0, 0.007)
	m.record_request('get', 200, 's', 0, 0, 0.02)
	out := m.render_prometheus()
	assert out.contains('cxstore_request_duration_seconds_bucket{endpoint="get",store="s",le="0.005"} 1'), out
	assert out.contains('cxstore_request_duration_seconds_bucket{endpoint="get",store="s",le="0.01"} 2'), out
	assert out.contains('cxstore_request_duration_seconds_bucket{endpoint="get",store="s",le="0.025"} 3'), out
	assert out.contains('cxstore_request_duration_seconds_bucket{endpoint="get",store="s",le="+Inf"} 3'), out
}

fn test_exposition_deterministic_order() {
	mut a := new_metrics_registry('v')
	mut b := new_metrics_registry('v')
	// record in different orders → identical output (keys are sorted)
	a.record_request('put', 200, 'docs', 1, 1, 0.01)
	a.record_request('get', 200, 'code', 1, 1, 0.01)
	b.record_request('get', 200, 'code', 1, 1, 0.01)
	b.record_request('put', 200, 'docs', 1, 1, 0.01)
	assert a.render_prometheus() == b.render_prometheus()
}

// ── label normalization → bounded cardinality ────────────────────────────────

fn test_label_normalization() {
	assert obs_norm_endpoint('get') == 'get'
	assert obs_norm_endpoint('metrics') == 'metrics'
	assert obs_norm_endpoint('wat') == '_other'
	assert obs_norm_endpoint('') == '_other'

	mounts := {
		'docs': cx.Node(cx.ScalarNode{})
		'code': cx.Node(cx.ScalarNode{})
	}
	assert obs_norm_store('docs', mounts) == 'docs'
	assert obs_norm_store('nope', mounts) == '_unknown'
	assert obs_norm_store('', mounts) == '_unknown'
}

// ── structured logs (F.3) ────────────────────────────────────────────────────

fn test_log_record_format() {
	// fixed inputs → exact, deterministic CX-element line
	got := svc_format_log('get', 'docs', 200, 3.25, 10, 100, 'reader', '', 1700000000, false)
	exp := '[request-log ts=1700000000 endpoint="get" store="docs" status=200 latency-ms=3.250 bytes-in=10 bytes-out=100 principal-role="reader"]'
	assert got == exp, got
}

fn test_log_record_includes_trace_id_when_present() {
	got := svc_format_log('put', 'docs', 201, 1.0, 5, 0, 'writer', 'abc123', 1700000000, false)
	assert got.contains('trace-id="abc123"'), got
	// absent trace-id omits the attribute entirely
	none_tid := svc_format_log('put', 'docs', 201, 1.0, 5, 0, 'writer', '', 1700000000, false)
	assert !none_tid.contains('trace-id'), none_tid
}

fn test_log_never_contains_secret() {
	// the formatter takes ROLE, not a token — there is no parameter through which
	// a secret could leak. Guard the property: a token-looking string never appears.
	got := svc_format_log('get', 'docs', 200, 0.5, 0, 0, 'metrics', 'tid', 1700000000, false)
	assert got.contains('principal-role="metrics"'), got
	assert !got.contains('Bearer'), got
	assert !got.to_lower().contains('secret'), got
}

fn test_log_sampling_suppresses_probes() {
	assert svc_log_sampled_out('health')
	assert svc_log_sampled_out('ready')
	assert !svc_log_sampled_out('get')
	assert !svc_log_sampled_out('metrics')
}

fn test_cardinality_bounded_under_bogus_stores() {
	mut m := new_metrics_registry('v')
	mounts := {
		'docs': cx.Node(cx.ScalarNode{})
	}
	// an attacker sprays 1000 distinct bogus store-names; normalization collapses
	// them all to `_unknown`, so the store-series count stays O(mounts)+1.
	for i in 0 .. 1000 {
		store := obs_norm_store('bogus-${i}', mounts)
		m.record_request('get', 200, store, 1, 1, 0.001)
	}
	m.record_request('get', 200, obs_norm_store('docs', mounts), 1, 1, 0.001)
	out := m.render_prometheus()
	// exactly two store label values appear: _unknown and docs
	assert out.contains('store="_unknown"'), out
	assert out.contains('store="docs"'), out
	assert m.requests.len == 2, 'expected 2 request series (docs + _unknown), got ${m.requests.len}'
}

// ── source: vcx/platform/store_observability_wave7_test.v ──
// store_observability_wave7_test.v — W7 observability (#200 span bytes/child/
// propagation, #202 async export, #207 minors). Deterministic where possible.
// ── #207.5: traceparent strictness (W3C) ──────────────────────────────────────

fn test_traceparent_rejects_uppercase() {
	// valid lowercase → accepted
	ok := parse_traceparent('00-0af7651916cd43dd8448eb211c80319c-b7ad6b7169203331-01')
	assert ok != none, 'valid lowercase traceparent must parse'
	// uppercase hex → invalid (W3C requires lowercase), not salvaged via to_lower
	up := parse_traceparent('00-0AF7651916CD43DD8448EB211C80319C-B7AD6B7169203331-01')
	assert up == none, 'uppercase traceparent must be rejected (#207.5)'
	// 5 fields on version 00 → invalid
	extra := parse_traceparent('00-0af7651916cd43dd8448eb211c80319c-b7ad6b7169203331-01-extra')
	assert extra == none, 'a 5-field version-00 traceparent must be rejected (#207.5)'
}

// ── #207.2: log format json ───────────────────────────────────────────────────

fn test_log_format_json() {
	j := svc_format_log('get', 'docs', 200, 3.25, 10, 100, 'reader', 'tid', 1700000000, true)
	assert j.starts_with('{') && j.ends_with('}'), 'json log must be a JSON object: ${j}'
	assert j.contains('"endpoint":"get"'), 'json log carries endpoint: ${j}'
	assert j.contains('"status":200'), 'json log carries numeric status: ${j}'
	assert j.contains('"trace-id":"tid"'), 'json log carries trace-id: ${j}'
	// the cx form is unchanged
	c := svc_format_log('get', 'docs', 200, 3.25, 10, 100, 'reader', 'tid', 1700000000, false)
	assert c.starts_with('[request-log'), 'cx log form unchanged: ${c}'
}

