fn test_child_span_otlp_parent() {
	parent := TraceContext{
		trace_id:  '0af7651916cd43dd8448eb211c80319c'
		span_id:   'b7ad6b7169203331'
		parent_id: ''
	}
	child := TraceContext{
		trace_id:  parent.trace_id
		span_id:   'aaaaaaaaaaaaaaaa'
		parent_id: parent.span_id
	}
	json := build_otlp_json([
