// ── #202: export enqueues (never blocks); disabled exporter is a no-op ─────────

fn test_async_export_enqueues_without_blocking() {
	// a black-hole endpoint: export() must return immediately (it enqueues; the
	// worker POSTs off the request path). We assert it returns and does not panic;
	// with cap 1024 the enqueue is non-blocking. (Latency is asserted end-to-end
	// in the integration harness; here we prove the call is fire-and-forget.)
	e := new_trace_exporter(true, 'http://127.0.0.1:1/v1/traces', 'cxstore')
	sp := Span{
		tc:   TraceContext{
			trace_id: '0af7651916cd43dd8448eb211c80319c'
			span_id:  'b7ad6b7169203331'
		}
		name: 'store.svc.get'
	}
	for _ in 0 .. 100 {
		e.export(sp) // must not block even though the collector is unreachable
	}
	// a disabled exporter is a pure no-op
	d := new_trace_exporter(false, '', 'cxstore')
	d.export(sp)
	assert true, 'export is fire-and-forget (#202)'
}

// ── source: vcx/platform/store_otel_e2_test.v ──
// store_otel_e2_test.v — #129 PR-B item 6 (E2 full OTel): the two completeness gaps that
// made the object wire fully observable. (1) the gRPC adapter forwards an inbound W3C
// `traceparent` so a gRPC hop CONTINUES the distributed trace (not a fresh root); (2) the
// object-wire verbs are first-class bounded-cardinality endpoints (metrics + span names),
// not collapsed to `_other`.

fn test_grpc_synth_forwards_traceparent() {
	tp := '00-${'0'.repeat(31)}1-${'0'.repeat(15)}1-01'
	req := grpc_synth_req('objects-put', 't', '[put]', map[string]string{}, '', tp)
	// the synthesized CSRP-equivalent request must carry the traceparent header so the
	// shared pipeline (svc_trace_for_request) continues the inbound trace.
	got := svc_request_header(req, 'traceparent')
	assert got == tp, 'grpc_synth_req must forward the inbound traceparent: ${got}'
	tc := svc_trace_for_request(req, false)
	assert tc.trace_id == '${'0'.repeat(31)}1', 'gRPC hop must continue the inbound trace-id: ${tc.trace_id}'
	assert tc.parent_id == '${'0'.repeat(15)}1', 'the inbound span becomes this span\'s parent'
	assert tc.span_id.len == 16 && tc.span_id != tc.parent_id, 'a fresh server span-id is minted'
}

fn test_grpc_synth_no_traceparent_is_root() {
	// no inbound traceparent → a fresh ROOT trace (no parent), ids still minted.
	req := grpc_synth_req('get', 't', '', {
		'hash': 'h'
	}, '', '')
	assert svc_request_header(req, 'traceparent') == '', 'no traceparent header when none inbound'
	tc := svc_trace_for_request(req, false)
	assert tc.trace_id.len == 32 && !obs_all_zero_hex(tc.trace_id), 'a root trace-id is minted'
	assert tc.parent_id == '', 'a root span has no parent'
}

fn test_object_wire_endpoints_are_observable() {
	// the #129 object wire must be observable per-verb (bounded cardinality), not _other.
	for ep in ['objects-have', 'objects-get', 'objects-put', 'refs', 'refs-set'] {
		assert obs_norm_endpoint(ep) == ep, '${ep} must be a first-class metrics/trace endpoint, not _other'
	}
	// a bogus op is still bounded to _other (no cardinality blow-up).
	assert obs_norm_endpoint('objects-frobnicate') == '_other', 'unknown ops stay bounded'
}

// ── source: vcx/platform/store_tracing_test.v ──
// store_tracing_test.v — BEHAVIORAL tests for W3C trace-context propagation, the
// span model, and OTLP/JSON serialization (observability O3, spec Appendix F.2).
// Deterministic: parsing/formatting/serialization are pure; id minting is checked
// for shape (length/hex), never value.

const tp_valid = '00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01'

fn test_parse_traceparent_valid() {
	tc := parse_traceparent(tp_valid) or { panic('should parse') }
	assert tc.trace_id == '4bf92f3577b34da6a3ce929d0e0e4736'
	assert tc.parent_id == '00f067aa0ba902b7'
	assert tc.sampled == true
}

fn test_parse_traceparent_unsampled_flag() {
	tc := parse_traceparent('00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-00') or {
		panic('should parse')
	}
	assert tc.sampled == false
}

fn test_parse_traceparent_rejects_malformed() {
	// empty
	if _ := parse_traceparent('') {
		assert false, 'empty should be none'
	}
	// wrong version
	if _ := parse_traceparent('ff-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01') {
		assert false, 'version ff should be none'
	}
	// too few fields
	if _ := parse_traceparent('00-4bf92f3577b34da6a3ce929d0e0e4736') {
		assert false, 'short should be none'
	}
	// all-zero trace-id
	if _ := parse_traceparent('00-00000000000000000000000000000000-00f067aa0ba902b7-01') {
		assert false, 'all-zero trace should be none'
	}
	// all-zero span-id
	if _ := parse_traceparent('00-4bf92f3577b34da6a3ce929d0e0e4736-0000000000000000-01') {
		assert false, 'all-zero span should be none'
	}
	// non-hex trace-id
	if _ := parse_traceparent('00-zzf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01') {
		assert false, 'non-hex trace should be none'
	}
}

fn test_id_minting_shape() {
	tid := obs_new_trace_id()
	sid := obs_new_span_id()
	assert obs_is_lc_hex(tid, 32), tid
	assert obs_is_lc_hex(sid, 16), sid
	assert !obs_all_zero_hex(tid), 'a minted trace id should not be all-zero'
}

fn test_format_traceparent() {
	tc := TraceContext{
		trace_id: '4bf92f3577b34da6a3ce929d0e0e4736'
		span_id:  '00f067aa0ba902b7'
		sampled:  true
	}
	assert format_traceparent(tc) == '00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01'
	tc2 := TraceContext{
		trace_id: '4bf92f3577b34da6a3ce929d0e0e4736'
		span_id:  '00f067aa0ba902b7'
		sampled:  false
	}
	assert format_traceparent(tc2).ends_with('-00')
}

fn trace_req(headers map[string]string) cx.Element {
	mut hdrs := []cx.Node{}
	for k, v in headers {
		hdrs << cx.Node(cx.Element{
			name:  'header'
			attrs: [
				cx.Attribute{
					name:  'name'
					value: cx.ScalarValue(k)
				},
				cx.Attribute{
					name:  'value'
					value: cx.ScalarValue(v)
				},
			]
		})
	}
	return cx.Element{
		name:  'request'
		items: [cx.Node(cx.Element{
			name:  'headers'
			items: hdrs
		})]
	}
}

fn test_trace_for_request_mints_root() {
	tc := svc_trace_for_request(trace_req(map[string]string{}), false)
	assert obs_is_lc_hex(tc.trace_id, 32), tc.trace_id
	assert obs_is_lc_hex(tc.span_id, 16), tc.span_id
	assert tc.parent_id == '', 'a fresh root has no parent'
}

fn test_trace_for_request_continues_inbound() {
	req := trace_req({
		'traceparent': tp_valid
	})
	tc := svc_trace_for_request(req, false)
	// same trace, NEW span, parent = the inbound span, sampled propagated
	assert tc.trace_id == '4bf92f3577b34da6a3ce929d0e0e4736'
	assert tc.parent_id == '00f067aa0ba902b7'
	assert tc.span_id != '00f067aa0ba902b7', 'server span must be a fresh id'
	assert obs_is_lc_hex(tc.span_id, 16), tc.span_id
	assert tc.sampled == true
}

fn test_otlp_status_mapping() {
	assert obs_otlp_status(200) == 1
	assert obs_otlp_status(404) == 1 // client error is not a span error
	assert obs_otlp_status(500) == 2
	assert obs_otlp_status(503) == 2
}

fn test_build_otlp_json_shape() {
	sp := Span{
		tc:       TraceContext{
			trace_id:  '4bf92f3577b34da6a3ce929d0e0e4736'
			span_id:   'a1a2a3a4a5a6a7a8'
			parent_id: '00f067aa0ba902b7'
			sampled:   true
		}
		name:     'store.svc.get'
		start_ns: 1700000000000000000
		end_ns:   1700000000003000000
		status:   200
		attrs:    {
			'endpoint': 'get'
			'store':    'docs'
		}
	}
	out := build_otlp_json([sp], 'cxstore')
	assert out.contains('"resourceSpans"'), out
	assert out.contains('"service.name"'), out
	assert out.contains('"traceId":"4bf92f3577b34da6a3ce929d0e0e4736"'), out
	assert out.contains('"spanId":"a1a2a3a4a5a6a7a8"'), out
	assert out.contains('"parentSpanId":"00f067aa0ba902b7"'), out
	assert out.contains('"name":"store.svc.get"'), out
	assert out.contains('"kind":2'), out
	assert out.contains('"startTimeUnixNano":"1700000000000000000"'), out
	assert out.contains('"endTimeUnixNano":"1700000000003000000"'), out
	// attributes serialized (sorted: endpoint before store)
	assert out.contains('{"key":"endpoint","value":{"stringValue":"get"}}'), out
	assert out.contains('"status":{"code":1}'), out
}

fn test_build_otlp_json_root_omits_parent() {
	sp := Span{
		tc:     TraceContext{
			trace_id: '4bf92f3577b34da6a3ce929d0e0e4736'
			span_id:  'a1a2a3a4a5a6a7a8'
		}
		name:   'store.svc.put'
		status: 500
	}
	out := build_otlp_json([sp], 'cxstore')
	assert !out.contains('parentSpanId'), out
	assert out.contains('"status":{"code":2}'), out // 5xx → Error
}

// ── source: vcx/platform/store_limits_test.v ──
// #105 brick E — DoS fairness limiter (deterministic: time injected as now_ns).

fn test_token_bucket_exhausts_and_refills() {
	mut l := new_limiter(LimitConfig{})
	// rate 1/s, burst 2 → two immediate, third denied, refills 1 after 1s.
	t0 := i64(0)
	assert l.allow_rate('k', 1.0, 2.0, t0) // 2 → 1
	assert l.allow_rate('k', 1.0, 2.0, t0) // 1 → 0
	assert !l.allow_rate('k', 1.0, 2.0, t0) // 0 → denied
	assert l.allow_rate('k', 1.0, 2.0, t0 + i64(1_000_000_000)) // +1 token → allowed
	assert !l.allow_rate('k', 1.0, 2.0, t0 + i64(1_000_000_000)) // back to 0
}

fn test_rate_unlimited_when_zero() {
	mut l := new_limiter(LimitConfig{})
	for i in 0 .. 1000 {
		assert l.allow_rate('k', 0.0, 0.0, i64(i)) // rate 0 → always allowed
	}
}

fn test_rate_anti_starvation_per_key() {
	mut l := new_limiter(LimitConfig{})
	// principal A exhausts its bucket; B (separate key) is unaffected.
	assert l.allow_rate('p:A', 1.0, 1.0, 0)
	assert !l.allow_rate('p:A', 1.0, 1.0, 0) // A throttled
	assert l.allow_rate('p:B', 1.0, 1.0, 0) // B still served — no starvation
}

fn test_concurrency_cap_and_release() {
	mut l := new_limiter(LimitConfig{})
	assert l.acquire('p:A', 2)
	assert l.acquire('p:A', 2)
	assert !l.acquire('p:A', 2) // at cap
	l.release('p:A')
	assert l.acquire('p:A', 2) // slot freed
	// a different principal has its own budget
	assert l.acquire('p:B', 2)
}

fn test_concurrency_unlimited_when_zero() {
	mut l := new_limiter(LimitConfig{})
	for _ in 0 .. 1000 {
		assert l.acquire('p:A', 0) // max 0 → unlimited
	}
}

fn test_release_never_negative() {
	mut l := new_limiter(LimitConfig{})
	l.release('p:A') // no-op when nothing held
	assert l.acquire('p:A', 1)
}

fn test_pre_auth_global_bucket() {
	mut l := new_limiter(LimitConfig{
		pre_auth_rate:  1.0
		pre_auth_burst: 1.0
	})
	assert l.allow_pre_auth() // 1 → 0
	assert !l.allow_pre_auth() // global pre-auth flood throttled
}

fn test_defaults_are_on_and_generous() {
	cfg := LimitConfig{}
	assert cfg.per_principal_conc == 64
	assert cfg.per_principal_rate == 50.0
	assert cfg.pre_auth_rate == 100.0
}
